#sidebar {
    position: fixed; left: -270px; top: 0; width: 240px; height: 100vh;
    background: rgba(2, 6, 23, 0.98); backdrop-filter: blur(15px); z-index: 100;
    transition: left 0.4s; border-right: 1px solid rgba(255,255,255,0.1);
